import java.util.Date;
	
		import org.apache.log4j.Logger;
	
		import sailpoint.connector.Connector;
		import sailpoint.object.ResourceObject;
		import sailpoint.tools.GeneralException;
		
		Logger logger = Logger.getLogger("IAM_COE_BIRTHRIGHT_PROVISIONING");
		if (logger.isTraceEnabled()) {
			logger.trace("Entered to Alpha-Rule-Customization-HRSoft-Application Rule!!!");
		}
		if(object.getObjectType().compareTo(Connector.TYPE_ACCOUNT)==0) {
			logger.debug("Alpha-Rule-Customization-HRSoft-Application -> ResourceObject : " +object.toXml());
			String status = (String)object.getAttribute("employeeStatus");
			
			/*if (status.equals("0")) {
				object.put("Status","Active");
				object.put("IIQDisabled",false);
			}
			else  {
				object.put("Status","InActive");
				object.put("IIQDisabled",true);
			}*/
			String employeeID = (String) object.getAttribute("employeeID");
			if (!employeeID.equalsIgnoreCase("sa_iiqrest")) {
				object.put("userType","Employee");
			}
		}
		logger.debug("Alpha-Rule-Customization-HRSoft-Application -> After Modified ResourceObject : " +object.toXml());
		if (logger.isTraceEnabled()) {
			logger.trace("Alpha-Rule-Customization-HRSoft-Application Rule Ended!!!");
		}
		return object;
